export const findProduct = (id: string): Product | undefined =>
  products.find((p) => p.id === id);

export const productsByCategory = (categoryId: string): Product[] =>
  products.filter((p) => p.categoryId === categoryId);

export const productsBySubcategory = (subcategoryId: string): Product[] =>
  products.filter((p) => p.subcategoryId === subcategoryId);

export const trendingProducts = (): Product[] =>
  products.filter((p) => p.trending).slice(0, 24);

export const featuredProducts = (): Product[] =>
  products.filter((p) => p.featured).slice(0, 24);

export const newArrivals = (): Product[] =>
  products.filter((p) => p.newArrival).slice(0, 24);

export const bestsellers = (): Product[] =>
  products.filter((p) => p.bestseller).slice(0, 24);
